#include "gemver.h"

void kernel_gemver(
    double alpha,
    double beta,
    double A[40][40],
    double u1[40],
    double v1[40],
    double u2[40],
    double v2[40],
    double w[40],
    double x[40],
    double y[40],
    double z[40]) {
    const int N = 40;
    int i, j;

    // Matrix update: A = A + u1 * v1^T + u2 * v2^T
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
        }
    }

    // Vector update: x = beta * A^T * y + z
    for (i = 0; i < N; i++) {
        x[i] = 0.0;
        for (j = 0; j < N; j++) {
            x[i] = x[i] + beta * A[j][i] * y[j];
        }
        x[i] = x[i] + z[i];
    }

    // Final vector computation: w = alpha * A * x
    for (i = 0; i < N; i++) {
        w[i] = 0.0;
        for (j = 0; j < N; j++) {
            w[i] = w[i] + alpha * A[i][j] * x[j];
        }
    }
}

